import{_ as a,o as t,c as r,a3 as _}from"./chunks/framework.DdpBa4_E.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/34-正式雇员与非正式雇员的差距.md","filePath":"books/xialiu-shehui/34-正式雇员与非正式雇员的差距.md","lastUpdated":1794732511000}'),p={name:"books/xialiu-shehui/34-正式雇员与非正式雇员的差距.md"};function o(s,e,i,n,l,c){return t(),r("div",null,[...e[0]||(e[0]=[_('<h2 id="正式雇员与非正式雇员的差距" tabindex="-1">正式雇员与非正式雇员的差距 <a class="header-anchor" href="#正式雇员与非正式雇员的差距" aria-label="Permalink to &quot;正式雇员与非正式雇员的差距&quot;">​</a></h2><p>另一个值得引起关注的现象是，在团块次代的女性中，有81%的调查对象认为收入差距在不断扩大，其中“上流”占76.5%，“中流”占75.0%，“下流”则令人诧异地高达93.6%。与男性相比，下流阶层的女性对于收入差距的不断扩大显得极为敏感。</p><p>这主要是因为，接受此次调查的团块次代女性中，约有21%的人为派遣雇员、计时临时工以及无固定职业的自由打工者。在这些非正式雇员中，阶层意识属于“上流”的仅为5.9%，属于“中流”的占25.0%，而属于“下流”的占22.6%。因而在这部分“中流”和“下流”的人群中，对于与从事相类似工作的正式雇员之间的收入差距大多有着强烈的切身感受。此外，还有一部分专业的家庭主妇在与没有放弃工作的同龄人进行比较时，也会强烈地意识到两者之间的收入差距，从而感觉收入差距在不断扩大。</p><p>对于成果主义，有64%的团块次代女性表示容忍，其中阶层意识“上流”者为76.4%，“中流”者为61.6%，“下流”者为61.3%。这一结果与男性的调查结果相反，越是上流阶层意识的人群反而对之越是持容忍的态度。</p><p>更加值得关注的是，对成果主义持容忍态度的比例，除了女性中的“上流”以外，包括男性在内的所有分组中都只占60%左右，唯独女性的“上流”却高达76%，这一支持率实在高得惊人。我们不妨这样设想，女性中的上流阶层与男性做着同样的工作，付出同样的辛劳，却得不到公正和完整的评价，因此，她们在感情上往往会更加倾向于成果主义。</p><p>对于论资排辈和终身雇佣制度，支持率仅有6%，其中在阶层意识“上流”的人群中支持率为零，在“中流”人群中为7.7%，在“下流”人群中为6.5%。由于女性并未享受到论资排辈和终身雇佣的好处，因而对之少有好感，特别是对于女性中的少数上流精英分子来说，论资排辈和终身雇佣制度无异于是男性社会对女性构筑的一道性别歧视的壁障，因而得不到一个人的赞同。</p><p>然而，并非所有调查对象中的上流女性都从事着与男性同样的工作，甚至还不乏不工作的女性，其中半数是家庭主妇。包含了不少与论资排辈、终身雇佣毫无利害关系的女性在内的“上流”，为什么如此支持成果主义而对论资排辈及终身雇佣制度却持强烈的否定态度呢？</p><p>不排除“上流”中只有职业女性做出强烈反应，而其余人并未作回答的可能性。但是查验了调查问卷却发现，在回答者中职业女性与专职家庭主妇的人数几乎没有什么差别。那么也有可能是，一部分现在的家庭主妇她们原来是与男性干着同样工作的职业女性，出于曾经的亲身体会而做出这样的回答；另外还有一种可能性便是，以上各种原因都不是，这些女性之所以这样回答，只是出于肯定成果主义而否定论资排辈和终身雇佣可能会对自己的丈夫更加有利。</p><p>不论是哪一种情况，就团块次代来说，以企业正式雇员为主的女性上流阶层为了反抗无能的上司以及男性构筑的性别歧视的壁障，于是强烈支持成果主义；而以无固定职业的自由打工族为主的女性下流阶层则是为了消除与正式雇员的差距，也殊途同归地支持成果主义。</p><p>然而在成果主义的旗帜下，胜出的人与失败的人之间差距却是非常大的，而与那些自由打工者等非正式雇员之间的差距就更加悬殊了。于是这里出现了一个非常棘手的问题：这种收入差距的扩大化（也就是下流化）的进程究竟能够被人们冷静地接受到什么样的程度？而那些没有取得显著成果因而收入在不断减少，却身负养育子女、住房还贷等巨大压力的人群，他们的生活将何去何从？这一问题也势必越来越严重，如果得不到很好的解决，日本的未婚化、少子化问题必将日益恶化。因为有一点是可以肯定的，那就是结婚、生育，普普通通地生活，维持普普通通的“中流”的生活越来越困难了。</p><p>本书由“<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a>”整理，<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a> 提供最新最全的优质电子书下载！！！</p>',11)])])}const u=a(p,[["render",o]]);export{d as __pageData,u as default};
